2. Basic Decoding Logic
```noir fn decode_rlp<let N: u32>(encoded: [u8; N]) -> RLPItem {
    if N == 0 {
        return RLPItem {
            item_type: 0,
            bytes_data: [0; 256],
            bytes_length: 0,
