    let bid_range_valid = (bid_commitment.amount >= min_bid) & (bid_commitment.amount <= max_bid);
    let deposit_valid = deposit_proof.verify();
    let sufficient_deposit = deposit_proof.range_max >= bid_commitment.amount;

    bid_range_valid & deposit_valid & sufficient_deposit
} ```

Vote encryption enables privacy-preserving tallying through homomorphic encryption. Implement encryption schemes that allow vote counting without revealing individual votes.
1. Vote Encryption
```noir fn encrypt_vote(vote: VoteChoice, randomness: Field, public_key: Field) -> Field {
    // Simple additive encryption for homomorphic tallying
    let vote_value = vote.to_field();
    vote_value + randomness // Simplified encryption
} ```
2. Vote Decryption
```noir fn decrypt_vote(encrypted_vote: Field, private_key: Field) -> VoteChoice {
    // Simplified decryption (in practice, would use proper decryption)
    let decrypted_value = encrypted_vote - private_key; // Simplified
    VoteChoice::from_field(decrypted_value)
} ```
3. Homomorphic Addition
```noir fn add_encrypted_votes(vote1: Field, vote2: Field) -> Field {
    vote1 + vote2 // Homomorphic addition
} ```
4. Vote Validity Proof
```noir fn prove_vote_validity(vote: VoteChoice, randomness: Field) -> Field {
    // Prove vote ∈ {1, 2, 3} without revealing which one
    let vote_value = vote.to_field();
    pedersen_hash([vote_value, randomness])
} ```
5. Batch Encryption
```noir fn encrypt_votes_batch(votes: [VoteChoice], randomness: [Field], public_key: Field) -> [Field] {
    let mut encrypted = [0; votes.len()];
    for i in 0..votes.len() {
        encrypted[i] = encrypt_vote(votes[i], randomness[i], public_key);
    }
    encrypted
} ```

Voter commitments enable anonymous voter registration while maintaining eligibility verification. Implement commitment schemes for voter identity management.
1. Voter Commitment Generation
```noir fn commitment(self) -> Field {
    pedersen_hash([self.voter_id, self.secret])
} ```
2. Vote Choice Encoding
```noir impl VoteChoice {
    fn to_field(self) -> Field {
        match self {
            VoteChoice::Yes => 1,
            VoteChoice::No => 2,
            VoteChoice::Abstain => 3
        }
    }

    fn from_field(value: Field) -> Self {
        if value == 1 {
            VoteChoice::Yes
        } else if value == 2 {
            VoteChoice::No
        } else {
            VoteChoice::Abstain
        }
    }
} ```
3. Voter Registry Management
```noir fn register_voter(&mut self, voter_commitment: Field) -> bool {
    // Check for duplicate registrations
    for existing in self.registered_voters {
        if existing == voter_commitment {
            return false;
        }
    }

    self.registered_voters.push(voter_commitment);
    true
} ```

Recursive proofs enable one Noir program to verify another program's proof within a zero-knowledge circuit. This powerful technique allows proof aggregation, where multiple proofs can be combined into a single proof, enabling scalable verification systems.
**Key Concepts:** - **Proof**: Array of field elements containing the cryptographic proof data (typically 93 fields for Noir) - **Public Inputs**: Values that are revealed during verification (not hidden by zero-knowledge) - **Key Hash**: Cryptographic hash of the verification key used to generate the original proof - **Aggregation**: Combining multiple proofs into one for efficient batch verification - **Chaining**: Linking proofs where one proof's output becomes another's input
**When to use recursive proofs:** - Batch verification of multiple transactions - Building proof trees for scalability - Creating privacy-preserving audit trails - Implementing roll-up style scaling solutions
1. Recursive Proof Verification
```noir
fn verify_recursive_proof(
    proof: [Field; 93],
    public_inputs: [Field; 1],
    key_hash: Field,
    public_input: Field
) -> bool {
    std::verify_proof(proof, public_inputs, key_hash, public_input)
}
```
2. Two-Proof Aggregation
```noir
fn aggregate_two_proofs(
    proof1: [Field; 93],
    public_inputs1: [Field; 1],
    proof2: [Field; 93],
    public_inputs2: [Field; 1],
    key_hash: Field
) -> bool {
    let proof1_valid = std::verify_proof(proof1, public_inputs1, key_hash, public_inputs1[0]);
    let proof2_valid = std::verify_proof(proof2, public_inputs2, key_hash, public_inputs2[0]);

    proof1_valid & proof2_valid
}
```
3. Chain Verification
```noir
fn chain_verification(
    proof1: [Field; 93],
    public_inputs1: [Field; 1],
    proof2: [Field; 93],
    public_inputs2: [Field; 1],
    key_hash: Field
) -> bool {
    // Verify first proof
    let proof1_valid = std::verify_proof(proof1, public_inputs1, key_hash, public_inputs1[0]);

    // Verify second proof depends on first proof's output
    let proof2_valid = std::verify_proof(proof2, public_inputs2, key_hash, public_inputs2[0]);

    // Check that proof2's input comes from proof1's output
    let chain_valid = public_inputs2[0] == public_inputs1[0];

    proof1_valid & proof2_valid & chain_valid
}
```
4. Recursive Function Pattern
```noir
#[recursive] fn simple_computation(x: Field, y: Field) -> pub Field {
    // Computation that can be recursively verified
    x * x + y * y
}
```
5. Main Verification Function
```noir
fn main(
    x: Field,
    y: Field,
    proof: [Field; 93],
    public_inputs: [Field; 1],
    key_hash: Field,
    expected_result: Field
) -> pub bool {
    let result = simple_computation(x, y);
    let computation_correct = result == expected_result;
    let proof_valid = verify_recursive_proof(proof, public_inputs, key_hash, public_inputs[0]);
    let test_computation = simple_computation(3, 4) == 25;

    computation_correct & proof_valid & test_computation
}
```
